"use client";

import React from "react";
import { AppBar, Stack, IconButton } from "@mui/material";
import Image from "next/image";
import { Bell } from "lucide-react";
import { useTheme } from "@mui/material/styles";
import { DesktopNav, MobileNav } from "./Nav";
import { UserAvatar, AnchorLink, AppButton, SearchBar } from "@repo/shared-ui";
import { img } from "@repo/assets";
import { useHeader } from "./useHeader";
import { CLIENT_ROUTES } from "@repo/core";

interface HeaderProps {
  scrollRef?: React.RefObject<HTMLElement | null>;
}

export const AppHeader: React.FC<HeaderProps> = ({ scrollRef }) => {
  const theme = useTheme();
  const {
    isLoggedIn,
    isDesktop,
    scrollDir,
    authStatus,
    menuRef,
    handleNotification,
    handleLogo,
    handleAvatar,
    navigateTo,
    authUser,
  } = useHeader(scrollRef);

  return (
    <AppBar
      position="sticky"
      component="nav"
      sx={{
        zIndex: 500,
        display: "flex",
        flexDirection: "row",
        justifyContent: "space-between",
        alignItems: "center",
        gap: theme.gap(4),
        backdropFilter: "blur(24px)",
        ...(!isDesktop && {
          transform:
            scrollDir === "down" ? "translateY(-100%)" : "translateY(0)",
          transition: "transform 0.3s ease-in-out",
        }),
      }}>
      {/* Logo */}
      <AnchorLink
        url={CLIENT_ROUTES.home.path}
        onClick={handleLogo}
        style={{ display: "inline-flex" }}>
        <Image
          src={img.logo}
          alt="logo"
          width={34}
          height={34}
          priority
          style={{
            borderRadius: theme.radius.full,
          }}
        />
      </AnchorLink>

      {/* Search */}
      {isDesktop && isLoggedIn && <SearchBar />}

      {/* Right controls */}
      <Stack direction="row" alignItems="center" spacing={theme.gap(6)}>
        {isLoggedIn && (
          <>
            {/* Notification */}
            <IconButton
              onClick={handleNotification}
              href={CLIENT_ROUTES.notifications.path}
              sx={{
                width: 36,
                height: 36,
                padding: theme.boxSpacing(4),
                border: `1px solid ${theme.palette.gray.trans[1]}`,
              }}>
              <Bell
                style={{ width: "100%", stroke: theme.palette.gray[200] }}
              />
            </IconButton>

            {/* User Avatar  */}
            {isDesktop && <DesktopNav menuRef={menuRef} />}
            <UserAvatar
              userInfo={authUser}
              toolTipValue="Open menu"
              style={{
                width: "34px",
                height: "34px",
                marginLeft: "unset!important",
                [theme.breakpoints.down("md")]: {
                  width: "28px",
                  height: "28px",
                },
              }}
              action={(event: React.MouseEvent<HTMLElement>) =>
                handleAvatar({
                  desktop: event,
                  mobile: {
                    header: (
                      <UserAvatar
                        userInfo={authUser}
                        style={{ width: "35px", height: "35px" }}
                      />
                    ),
                    content: <MobileNav />,
                  },
                })
              }
            />
          </>
        )}

        {/* Login Button */}
        {authStatus === "UNAUTHENTICATED" && (
          <AppButton
            href={CLIENT_ROUTES.login.path}
            variant="outlined"
            style={{ fontSize: "14px" }}
            onClick={() =>
              navigateTo(CLIENT_ROUTES.login, { savePage: false })
            }>
            Login
          </AppButton>
        )}
      </Stack>
    </AppBar>
  );
};
